'use client'

import React, { useState } from 'react'
import { Button } from '@/components/ui/Button'
import { motion } from 'framer-motion'
import { Mail, Phone, MapPin, Clock, Send, CheckCircle } from 'lucide-react'

const container = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1,
    },
  },
}

const item = {
  hidden: { opacity: 0, y: 20 },
  show: { opacity: 1, y: 0 }
}

export default function ContactPage() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    subject: '',
    message: '',
  })
  const [submitted, setSubmitted] = useState(false)
  const [loading, setLoading] = useState(false)

  const handleChange = (e: any) => {
    setFormData({ ...formData, [e.target.name]: e.target.value })
  }

  const handleSubmit = async (e: any) => {
    e.preventDefault()
    setLoading(true)

    try {
      const response = await fetch('/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      })

      if (response.ok) {
        setSubmitted(true)
        setFormData({ name: '', email: '', phone: '', subject: '', message: '' })
        setTimeout(() => setSubmitted(false), 5000)
      }
    } catch (error) {
      console.error('Error:', error)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="bg-[var(--bg-primary)] min-h-screen pt-40 pb-32">
      {/* Hero */}
      <section className="px-6 max-w-[1400px] mx-auto mb-24">
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center space-y-6 mb-16"
        >
          <span className="text-xs font-bold uppercase tracking-[0.4em] text-[var(--accent-earth)]">Get in Touch</span>
          <h1 className="text-6xl md:text-7xl font-black tracking-tighter leading-tight">
            Let's Plan Your <br /> Next <span className="text-[var(--accent-earth)]">Adventure</span>
          </h1>
          <p className="text-xl text-[var(--text-secondary)] max-w-2xl mx-auto">
            Have questions? Need personalized recommendations? Our travel experts are here to help you create the perfect itinerary.
          </p>
        </motion.div>
      </section>

      {/* Main Content */}
      <section className="px-6 max-w-[1400px] mx-auto mb-24">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
          
          {/* Contact Form */}
          <motion.div 
            variants={container}
            initial="hidden"
            whileInView="show"
            className="space-y-8"
          >
            <div>
              <span className="text-xs font-bold uppercase tracking-[0.4em] text-[var(--accent-earth)] block mb-3">Contact Form</span>
              <h2 className="text-4xl font-black tracking-tighter mb-4">Send us a Message</h2>
              <p className="text-[var(--text-secondary)]">Fill out the form and we'll get back to you within 24 hours.</p>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Name */}
              <motion.div variants={item}>
                <label className="block text-sm font-bold mb-3">Full Name *</label>
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  required
                  className="w-full px-6 py-4 rounded-xl border border-gray-200 focus:border-[var(--accent-earth)] focus:outline-none transition-colors bg-white"
                  placeholder="John Doe"
                />
              </motion.div>

              {/* Email */}
              <motion.div variants={item}>
                <label className="block text-sm font-bold mb-3">Email Address *</label>
                <input
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  required
                  className="w-full px-6 py-4 rounded-xl border border-gray-200 focus:border-[var(--accent-earth)] focus:outline-none transition-colors bg-white"
                  placeholder="john@example.com"
                />
              </motion.div>

              {/* Phone */}
              <motion.div variants={item}>
                <label className="block text-sm font-bold mb-3">Phone Number *</label>
                <input
                  type="tel"
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  required
                  className="w-full px-6 py-4 rounded-xl border border-gray-200 focus:border-[var(--accent-earth)] focus:outline-none transition-colors bg-white"
                  placeholder="+91 99999 00000"
                />
              </motion.div>

              {/* Subject */}
              <motion.div variants={item}>
                <label className="block text-sm font-bold mb-3">Subject *</label>
                <input
                  type="text"
                  name="subject"
                  value={formData.subject}
                  onChange={handleChange}
                  required
                  className="w-full px-6 py-4 rounded-xl border border-gray-200 focus:border-[var(--accent-earth)] focus:outline-none transition-colors bg-white"
                  placeholder="What's this about?"
                />
              </motion.div>

              {/* Message */}
              <motion.div variants={item}>
                <label className="block text-sm font-bold mb-3">Message *</label>
                <textarea
                  name="message"
                  value={formData.message}
                  onChange={handleChange}
                  required
                  rows={6}
                  className="w-full px-6 py-4 rounded-xl border border-gray-200 focus:border-[var(--accent-earth)] focus:outline-none transition-colors bg-white resize-none"
                  placeholder="Tell us about your dream trip..."
                />
              </motion.div>

              {/* Submit */}
              <motion.div variants={item}>
                <Button 
                  type="submit" 
                  variant="primary" 
                  className="w-full !py-4 !rounded-xl flex items-center justify-center gap-2"
                  disabled={loading}
                >
                  {loading ? 'Sending...' : <>Send Message <Send className="w-4 h-4" /></>}
                </Button>
              </motion.div>

              {/* Success Message */}
              {submitted && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="p-6 bg-green-50 border border-green-200 rounded-xl flex items-center gap-3 text-green-700"
                >
                  <CheckCircle className="w-6 h-6 flex-shrink-0" />
                  <div>
                    <p className="font-bold">Message sent successfully!</p>
                    <p className="text-sm">We'll be in touch soon.</p>
                  </div>
                </motion.div>
              )}
            </form>
          </motion.div>

          {/* Contact Information */}
          <motion.div 
            variants={container}
            initial="hidden"
            whileInView="show"
            className="space-y-8"
          >
            <div>
              <span className="text-xs font-bold uppercase tracking-[0.4em] text-[var(--accent-earth)] block mb-3">Get in Touch</span>
              <h2 className="text-4xl font-black tracking-tighter mb-4">Contact Information</h2>
              <p className="text-[var(--text-secondary)]">Multiple ways to reach our world-class customer service team.</p>
            </div>

            {/* Contact Cards */}
            <motion.div variants={item} className="space-y-4">
              {[
                {
                  icon: Phone,
                  title: "Phone",
                  content: "+91 99998 08162",
                  subtext: "Available 24/7 for emergencies",
                },
                {
                  icon: Mail,
                  title: "Email",
                  content: "hello@ghumoholidays.com",
                  subtext: "Reply within 24 hours",
                },
                {
                  icon: MapPin,
                  title: "Office",
                  content: "New Delhi, India",
                  subtext: "Located in Cyber City",
                },
                {
                  icon: Clock,
                  title: "Working Hours",
                  content: "9:00 AM - 9:00 PM",
                  subtext: "Monday - Sunday",
                },
              ].map((contact, idx) => {
                const Icon = contact.icon
                return (
                  <div key={idx} className="bg-white rounded-2xl p-8 shadow-lg hover:shadow-xl transition-shadow border border-gray-100">
                    <div className="flex items-start gap-4">
                      <div className="w-12 h-12 rounded-full bg-[var(--accent-earth)]/10 flex items-center justify-center text-[var(--accent-earth)] flex-shrink-0">
                        <Icon className="w-6 h-6" />
                      </div>
                      <div>
                        <p className="text-xs font-bold uppercase tracking-widest text-[var(--text-muted)] mb-2">{contact.title}</p>
                        <p className="text-lg font-bold text-[var(--text-primary)]">{contact.content}</p>
                        <p className="text-sm text-[var(--text-secondary)]">{contact.subtext}</p>
                      </div>
                    </div>
                  </div>
                )
              })}
            </motion.div>

            {/* FAQ */}
            <motion.div variants={item} className="bg-gradient-to-br from-[var(--accent-earth)]/5 to-[var(--accent-teal)]/5 rounded-2xl p-10">
              <h3 className="font-black text-xl mb-6">Frequently Asked Questions</h3>
              <div className="space-y-4 text-sm">
                {[
                  { q: "How far in advance should I book?", a: "We recommend booking 6-8 weeks in advance for the best prices and availability." },
                  { q: "What payment methods do you accept?", a: "We accept credit cards, debit cards, UPI, and bank transfers." },
                  { q: "Can I customize my itinerary?", a: "Absolutely! All our packages can be customized to your preferences." },
                  { q: "What's your cancellation policy?", a: "Varies by package. Contact us for specific details." },
                ].map((faq, idx) => (
                  <div key={idx}>
                    <p className="font-bold text-[var(--text-primary)] mb-1">Q: {faq.q}</p>
                    <p className="text-[var(--text-secondary)] pl-4 border-l-2 border-[var(--accent-earth)]">A: {faq.a}</p>
                  </div>
                ))}
              </div>
            </motion.div>
          </motion.div>
        </div>
      </section>
    </div>
  )
}
